import "server-only";
import { randomUUID } from "node:crypto";
import { z } from "zod";
import { db } from "@/lib/db";
import type { PrismaClient } from "@/generated/prisma/client";
import { AppError } from "@/lib/errors";

export const budgets = {
  checkout: { limit: 5, windowMs: 600_000 },
  billingManagement: { limit: 10, windowMs: 60_000 },
  status: { limit: 30, windowMs: 60_000 },
  campaign: { limit: 10, windowMs: 60_000 },
  csv: { limit: 5, windowMs: 3_600_000 },
  export: { limit: 2, windowMs: 3_600_000 },
  admin: { limit: 20, windowMs: 60_000 },
  systemActor: { limit: 5, windowMs: 60_000 },
  systemGlobal: { limit: 10, windowMs: 60_000 },
} as const;
export type Budget = keyof typeof budgets;
export class RateLimitError extends AppError {
  readonly code = "RATE_LIMITED";
  constructor(readonly retryAfter: number) {
    super("Too many requests. Try again after the indicated delay.");
  }
}
export class RateLimitUnavailable extends AppError {
  readonly code = "UNAVAILABLE";
  constructor() {
    super("This operation is temporarily unavailable. Try again shortly.");
  }
}
export function rollingAdmission(
  times: Date[],
  now: Date,
  budget: { limit: number; windowMs: number },
) {
  const recent = times
    .filter((t) => +t > +now - budget.windowMs)
    .sort((a, b) => +a - +b);
  if (recent.length >= budget.limit)
    return {
      admitted: false as const,
      times: recent.slice(-budget.limit),
      retryAfter: Math.max(
        1,
        Math.ceil(
          (+recent[recent.length - budget.limit] + budget.windowMs - +now) /
            1000,
        ),
      ),
    };
  return { admitted: true as const, times: [...recent, now], retryAfter: 0 };
}
// Call after authentication, before parsing or side effects. Never pass a business
// transaction: admissions must survive rollback of the requested operation.
export async function consumeBudgets(
  ownerId: string,
  operations: Budget[],
  client: PrismaClient = db,
) {
  if (!z.uuid().safeParse(ownerId).success) throw new RateLimitUnavailable();
  const entries = [...new Set(operations)]
    .map((operation) => ({
      operation,
      scope: operation === "systemGlobal" ? "global" : ownerId,
    }))
    .sort((a, b) =>
      `${a.scope}:${a.operation}`.localeCompare(`${b.scope}:${b.operation}`),
    );
  try {
    const denied = await client.$transaction(
      async (tx) => {
        for (const { scope, operation } of entries) {
          await tx.$executeRaw`INSERT INTO "RateLimitBucket" (id,scope,operation,admissions,"cleanupAt") VALUES (${randomUUID()}::uuid,${scope},${operation},ARRAY[]::timestamp[],clock_timestamp()) ON CONFLICT (scope,operation) DO NOTHING`;
          await tx.$queryRaw`SELECT id FROM "RateLimitBucket" WHERE scope=${scope} AND operation=${operation} FOR UPDATE`;
        }
        // Obtain time after all locks: waiting for a hot budget cannot admit using stale time.
        const [{ now }] = await tx.$queryRaw<
          { now: Date }[]
        >`SELECT clock_timestamp() AS now`;
        const updates = [];
        let retryAfter = 0;
        for (const { scope, operation } of entries) {
          const bucket = await tx.rateLimitBucket.findUniqueOrThrow({
            where: { scope_operation: { scope, operation } },
          });
          const result = rollingAdmission(
            bucket.admissions,
            now,
            budgets[operation],
          );
          if (!result.admitted)
            retryAfter = Math.max(retryAfter, result.retryAfter);
          updates.push({ scope, operation, result });
        }
        if (retryAfter) return retryAfter;
        for (const { scope, operation, result } of updates)
          await tx.rateLimitBucket.update({
            where: { scope_operation: { scope, operation } },
            data: {
              admissions: result.times,
              cleanupAt: new Date(+now + budgets[operation].windowMs),
            },
          });
        return 0;
      },
      { maxWait: 5000, timeout: 10000 },
    );
    if (denied) throw new RateLimitError(denied);
  } catch (error) {
    if (error instanceof RateLimitError) throw error;
    throw new RateLimitUnavailable();
  }
}
export function rateLimitHttpError(error: unknown) {
  if (!(
    error instanceof RateLimitError || error instanceof RateLimitUnavailable
  ))
    return null;
  return Response.json(
    { code: error.code, error: error.message },
    {
      status: error instanceof RateLimitError ? 429 : 503,
      headers: {
        "Cache-Control": "private, no-store",
        ...(error instanceof RateLimitError
          ? { "Retry-After": String(error.retryAfter) }
          : {}),
      },
    },
  );
}
